<?php require 'db.php'; if(current_user()){header('Location: profile.php');exit;} $error=null; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';$s=$pdo->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch();if(!$u||!password_verify($pw,$u['password_hash'])){$error='Invalid email or password.';}else{login_user($u);$to=$_SESSION['return_to']??'profile.php';unset($_SESSION['return_to']);header('Location: '.$to);exit;}} $msg=flash('message');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login | Ceylon Spice Hub</title><link rel="stylesheet" href="style.css"></head><body><header class="header"><div class="container nav-wrap"><a class="brand" href="index.php"><span>Ceylon</span><small>SPICE HUB</small></a><a href="index.php" class="text-link">← Back to shop</a></div></header><main class="auth-page"><div class="auth-card"><p class="eyebrow">WELCOME BACK</p><h1>Sign in</h1><p class="muted">Log in to manage your profile and continue to checkout securely.</p><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><?php if($msg):?><div class="form-success"><?=e($msg)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Email Address<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn btn-primary auth-submit">LOGIN</button></form><p class="auth-switch">New customer? <a href="register.php">Create an account</a></p></div></main></body></html>